"""Public business assessment and buyer worksheet. Optional private browser save for assessment answers."""
import json, html
from pathlib import Path
from directory_brand import brand_page
ROOT=Path(__file__).resolve().parent
STYLE='''body{font:16px/1.6 system-ui;color:#252525;background:#faf9f6;margin:0}main{max-width:950px;margin:auto;padding:24px}a{color:#a90000}h1{line-height:1.15}section,article{background:white;border:1px solid #ccc;padding:20px;margin:18px 0;break-inside:avoid}label{display:block;margin:10px 0}input,select,button{font:inherit;padding:8px;max-width:100%;box-sizing:border-box}input{border:1px solid #888}textarea{width:100%;min-height:70px}button{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:8px;text-align:left}.muted{color:#555;font-size:.9rem}.actions{display:flex;flex-wrap:wrap;gap:12px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #ba0c2f}@media print{body{background:white}main{padding:0}.actions,.vhg-brand,.knowledge-links{display:none}input,textarea,select{border:1px solid #aaa}section{padding:12px;margin:12px 0}}'''
def shell(title,body,js=''):
 return brand_page('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+STYLE+'__VHG_CSS__</style></head><body><main>__VHG_BRAND__<a href="index.html">Directory home</a><h1>'+title+'</h1>'+body+'</main><script>'+js+'</script></body></html>')
def main():
 data=json.loads((ROOT/'data/business-assessment.json').read_text());cards=[]
 for q in data['questions']:
  cards.append('<article><h2>'+html.escape(q['id']+' · '+q['domain'])+'</h2><p>'+html.escape(q['question'])+'</p><p class="muted">Evidence: '+html.escape(q['evidence'])+' · Weight '+str(q['weight'])+'</p><label>Score <select data-id="'+q['id']+'" data-weight="'+str(q['weight'])+'"><option value="">Not assessed</option>'+''.join('<option value="'+str(n)+'">'+str(n)+' - '+s+'</option>' for n,s in enumerate(['Absent / unknown','Informal / partial','Documented','Implemented and evidenced']))+'</select></label><label>Evidence / owner / next action<textarea data-note="'+q['id']+'"></textarea></label></article>')
 body='''<p>Travis Vought's 33-question diagnostic for Ohio cannabis businesses preparing for banking, financing or internal review.</p><p>Imported from your v2 workbook, dated August 27, 2026. Its regulatory references have not been revalidated for this October edition. This measures documented operational readiness; it does not certify compliance or guarantee bank acceptance.</p><p>Score what you can demonstrate today. Start with weight-3 questions scored zero, then other zero scores and critical partial controls. Answers remain private on this device. Choose Save on this device to resume later; Clear saved answers removes the saved copy and resets this page. Export a copy before clearing browser data. No answers or notes are sent to analytics.</p><p><a href="data/business-assessment.json">Download blank question set</a></p><div class="actions"><button id="save" data-track="assessment-save">Save on this device</button><button id="clear" data-track="assessment-clear">Clear saved answers</button><span id="save-status" role="status"></span><button id="export" data-track="assessment-export">Export my answers</button><button id="print" data-track="assessment-print">Print my assessment</button></div><section><h2>Your progress</h2><p id="score" aria-live="polite">Not assessed.</p><p id="domains"></p><h3>Priority action plan</h3><ul id="priorities"></ul></section><form id="assessment-form">'''+''.join(cards)+'</form><p>After the assessment, use the <a href="index.html?category=Banking+%26+Financial+Services">banking directory</a>, <a href="index.html?category=Accounting+%26+Tax">accounting directory</a> or <a href="index.html?category=Legal+%26+Licensing">legal directory</a> to find support.</p>'
 js='''const qs='''+json.dumps(data['questions']).replace('<','\\u003c')+''';const fields=[...document.querySelectorAll('select[data-weight]')];function calculate(){const answered=fields.filter(e=>e.value!=='');const weight=answered.reduce((s,e)=>s+Number(e.dataset.weight),0);const points=answered.reduce((s,e)=>s+Number(e.value)/3*Number(e.dataset.weight),0);const pct=weight?100*points/weight:null;const critical=answered.filter(e=>e.dataset.weight==='3'&&e.value==='0').length;document.getElementById('score').textContent=answered.length+'/'+fields.length+' assessed. '+(pct===null?'No score yet.':(answered.length<fields.length?'Partial score (answered items only): ':'Overall readiness: ')+pct.toFixed(1)+'%. ')+(answered.length===fields.length?(critical?'RED - Address critical zero-score gaps before relying on the overall percentage. ':pct>=80?'GREEN - Strong readiness. ':pct>=60?'YELLOW - Improvement needed. ':'RED - Material gaps. '):'Finish all questions before using an overall rating. ')+critical+' critical zero-score gaps.';document.getElementById('domains').textContent=[...new Set(qs.map(q=>q.domain))].map(d=>{const group=qs.filter(q=>q.domain===d),ans=group.map(q=>fields.find(f=>f.dataset.id===q.id)).filter(f=>f.value!=='');const w=ans.reduce((s,f)=>s+Number(f.dataset.weight),0),p=ans.reduce((s,f)=>s+Number(f.value)/3*Number(f.dataset.weight),0);return d+': '+ans.length+'/'+group.length+' assessed'+(w?' / '+(100*p/w).toFixed(1)+'% (answered items)':'');}).join(' · ');const list=document.getElementById('priorities');list.replaceChildren();const gaps=answered.filter(f=>Number(f.value)<3).sort((a,b)=>(b.dataset.weight==='3'&&b.value==='0')-(a.dataset.weight==='3'&&a.value==='0')||Number(a.value)-Number(b.value)||Number(b.dataset.weight)-Number(a.dataset.weight));gaps.forEach(f=>{const q=qs.find(q=>q.id===f.dataset.id),li=document.createElement('li');li.textContent=q.id+' · '+q.question+' Evidence to establish: '+q.evidence;list.appendChild(li);});if(!gaps.length) {const li=document.createElement('li');li.textContent=answered.length===fields.length?'Maintain evidence and schedule the next review.':'Answer questions to identify priority actions.';list.appendChild(li);}}fields.forEach(e=>e.addEventListener('change',calculate));document.getElementById('print').onclick=()=>window.print();document.getElementById('export').onclick=()=>{const rows=qs.map(q=>({...q,score:fields.find(e=>e.dataset.id===q.id).value,notes:document.querySelector('[data-note="'+q.id+'"]').value}));const u=URL.createObjectURL(new Blob([JSON.stringify({assessment:rows},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='my-business-assessment.json';a.click();URL.revokeObjectURL(u);};const storageKey='ohio-business-assessment-v1';document.getElementById('save').onclick=()=>{try{localStorage.setItem(storageKey,JSON.stringify(fields.map(f=>({id:f.dataset.id,score:f.value,note:document.querySelector('[data-note="'+f.dataset.id+'"]').value}))));document.getElementById('save-status').textContent='Saved on this device.';}catch(e){document.getElementById('save-status').textContent='Browser storage unavailable. Export your answers instead.';}};document.getElementById('clear').onclick=()=>{try{localStorage.removeItem(storageKey);}catch(e){}fields.forEach(f=>f.value='');document.querySelectorAll('textarea[data-note]').forEach(n=>n.value='');calculate();document.getElementById('save-status').textContent='Answers cleared.';};try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))saved.forEach(r=>{const f=fields.find(f=>f.dataset.id===r.id);if(f&&['','0','1','2','3'].includes(r.score)){f.value=r.score;document.querySelector('[data-note="'+r.id+'"]').value=typeof r.note==='string'?r.note:'';}});}catch(e){}calculate();'''
 (ROOT/'assessment.html').write_text(shell('Business financial access & compliance self-assessment',body,js))
 body='''<p>A first-visit guide and shopping worksheet. Start with your goal and experience, then discuss product, strength and budget with dispensary staff. Your answers stay on this page and are not saved or sent.</p><div class="actions"><a href="assets/dispensary-shopping-guide.pdf">Download printable guide (PDF)</a><a href="assets/dispensary-visit-companion.pdf" data-track="download-visit-companion">Download visit plan + experience journal (PDF)</a><button id="print" data-track="buyer-guide-print">Print my worksheet</button></div><section><h2>What are you trying to accomplish?</h2><label>My goal / what I want to ask about <input style="width:100%" placeholder="Relaxation, product education, avoiding smoke, or a concern to discuss with a clinician"></label><label>Experience <select><option>First time</option><option>Occasional</option><option>Returning after a break</option><option>Experienced, new product form</option></select></label><label>Budget including tax / fees $ <input type="number" min="0"></label><label>Product <select><option>Gummies / edibles</option><option>Flower / pre-rolls</option><option>Concentrates / cartridges</option><option>Tincture / oral oil</option><option>Topicals</option><option>Not sure</option></select></label><label>Preferences / ingredients to avoid <input style="width:100%"></label></section><section><h2>How long will my purchase last?</h2><p>Use the same unit for package quantity and amount per use: pieces for gummies, mL for oil, grams for flower or concentrate. These are shopping estimates, not dose recommendations. Leave blank if you do not yet know your amount.</p><label>Quantity in one package <input id="quantity" type="number" min="0" step="any"></label><label>Unit <select id="unit"><option>pieces</option><option>mL</option><option>grams</option></select></label><label>Planned amount per use <input id="amount" type="number" min="0" step="any"></label><label>Planned uses per week <input id="frequency" type="number" min="0" step="any"></label><label>Weeks I want covered <input id="weeks" type="number" min="0" step="any"></label><p id="estimate" aria-live="polite">Enter your own estimates to calculate supply duration.</p><p>Example: 10 gummies, one-quarter gummy per use, twice per week = 40 uses or 20 weeks. This says nothing about the appropriate THC amount. Check mg THC per gummy and whether it can be portioned reliably. Buy a small trial amount first when your response is unknown.</p></section><section id="label-math"><h2>Understand THC and CBD on the label</h2><p>Calculate labeled content in an amount you enter. This does not recommend an amount, predict effects or calculate absorbed THC. Use the label basis exactly as printed; do not substitute THCA for total THC.</p><label>Label basis <select id="label-basis"><option value="piece">mg per piece</option><option value="ml">mg per mL</option><option value="package">mg per whole package</option><option value="percent">Percent by weight</option></select></label><label>THC on label <input id="label-thc" type="number" min="0" step="any"></label><label>CBD on label (optional) <input id="label-cbd" type="number" min="0" step="any"></label><label id="label-amount-text" for="label-amount">Amount in pieces</label><input id="label-amount" type="number" min="0" step="any"><p id="label-result" aria-live="polite">Enter labeled THC and your amount to calculate labeled content.</p><p>Examples: 10 mg per gummy x 0.25 gummy = 2.5 mg labeled THC. 20% x 0.1 grams x 10 = 20 mg labeled THC in the material, which does not establish what you absorb. Dividing a product may not distribute cannabinoids evenly.</p></section><section><h2>Take a plan with you, then record your experience</h2><p>The <a href="assets/dispensary-visit-companion.pdf">two-page visit companion</a> has a one-page handoff starting with your goal, budget, preferences and label questions, followed by a personal experience journal. Print page 1 for the visit and page 2 for later notes.</p><p>Record product and batch, form, labeled content, amount used, onset, duration, helpful and unwanted effects, and questions for your next visit. Keep notes private; they do not establish a safe dose or fitness to drive.</p></section><section><h2>Ask before buying</h2><ul><li>How much THC and CBD are in one serving and the whole package?</li><li>How is this used, and when do effects begin, peak and wear off?</li><li>Can it be measured or divided reliably? What device is required?</li><li>What is the final cost with taxes, fees and any device?</li><li>Are there allergens, added ingredients or a batch testing report?</li><li>How should I store it securely, and what is the expiration date?</li></ul><p>For new or occasional edible users, Health Canada gives a starting reference of 2.5 mg THC or less and advises allowing up to four hours for full effects before taking more. Higher-potency extracts can be difficult for beginners to measure. Oral oils used under the tongue and swallowed oils can behave differently. Ask a clinician or pharmacist about medicines and health concerns.</p><p>Do not drive while impaired. Keep products locked away from children and pets. Avoid combining with alcohol. Strain names do not guarantee effects.</p><p>For Ohio adult-use purchases, bring current government-issued photo ID showing you are 21 or older. Medical purchasers should bring their active registry card and linked ID and have an active recommendation. Confirm store payment options and hours before travel.</p><p><a href="https://www.canada.ca/en/health-canada/services/drugs-medication/cannabis/resources/lower-your-risks.html">Health Canada: lower-risk starting guidance</a> · <a href="https://codes.ohio.gov/ohio-administrative-code/rule-1301:18-8-08">Ohio adult-use dispensing rule</a> · <a href="knowledge.html">Product forms and labels</a></p></section>'''
 js='''function labelCalc(){const basis=document.getElementById('label-basis').value;const units={piece:'pieces',ml:'mL',package:'fraction of the whole package (0 to 1)',percent:'grams'};document.getElementById('label-amount-text').textContent='Amount in '+units[basis];const thc=document.getElementById('label-thc'),cbd=document.getElementById('label-cbd'),amount=document.getElementById('label-amount'),out=document.getElementById('label-result');const t=Number(thc.value),c=Number(cbd.value),a=Number(amount.value);if(thc.value===''||amount.value===''){out.textContent='Enter labeled THC and your amount to calculate labeled content.';return;}if(![t,c,a].every(Number.isFinite)||t<0||c<0||a<=0||(basis==='percent'&&(t>100||c>100||(cbd.value!==''&&t+c>100)))||(basis==='package'&&a>1)){out.textContent='Check inputs: use nonnegative label values, a positive amount, percentages totaling no more than 100%, and a package fraction no greater than 1.';return;}const multiplier=basis==='percent'?a*10:a;out.textContent='Labeled content in your entered amount: '+(t*multiplier).toFixed(2)+' mg THC'+(cbd.value!==''?' and '+(c*multiplier).toFixed(2)+' mg CBD':'; CBD not entered')+'. This is content arithmetic, not absorbed dose or expected effect.';}['label-thc','label-cbd','label-amount'].forEach(id=>document.getElementById(id).addEventListener('input',labelCalc));document.getElementById('label-basis').addEventListener('change',labelCalc);labelCalc();const inputs=['quantity','amount','frequency','weeks'];function calc(){const [q,a,f,w]=inputs.map(id=>Number(document.getElementById(id).value));const o=document.getElementById('estimate');if(!(q>0&&a>0&&f>0)){o.textContent='Enter positive package quantity, amount per use and uses per week.';return;}const uses=q/a;const weeks=uses/f;o.textContent='One package: about '+uses.toFixed(1)+' uses, lasting '+weeks.toFixed(1)+' weeks ('+(weeks*7).toFixed(0)+' days).'+(w>0?' To cover '+w+' weeks: '+(a*f*w).toFixed(2)+' '+document.getElementById('unit').value+'; '+Math.ceil(a*f*w/q)+' whole packages.':'')+' Actual use, waste and shelf life may differ.';}inputs.forEach(id=>document.getElementById(id).addEventListener('input',calc));document.getElementById('unit').addEventListener('change',calc);document.getElementById('print').onclick=()=>window.print();'''
 (ROOT/'buyer-guide.html').write_text(shell('Your dispensary shopping plan',body,js))
if __name__=='__main__':main()
